// ../snapshot/src/index.ts
var escapeHtml2 = (text) => text.replace(
  /[&<>"']/g,
  (char) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[char]
);
function renderSnapshot(report) {
  const json = JSON.stringify(report).replace(
    /[<>&\u2028\u2029]/g,
    (char) => `\\u${char.charCodeAt(0).toString(16).padStart(4, "0")}`
  );
  return `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src data:; font-src data:; connect-src 'none'; base-uri 'none'; form-action 'none'">
<meta name="description" content="A portable snapshot of Brocante\u2019s 3D pull-request marketplace.">
<title>${escapeHtml2(report.repository)} \xB7 Brocante</title><style>${styles}</style></head>
<body><div id="brocante"></div><noscript>This marketplace requires JavaScript.</noscript>
<script type="application/json" id="brocante-data">${json}</script><script>${script}</script></body></html>
`;
}

// src/server.ts
import { randomUUID } from "node:crypto";
function plugin(bb) {
  const settings = bb.settings.define({
    githubToken: { type: "string", label: "GitHub read-only token", secret: true }
  });
  let retryAt = 0;
  const snapshots = () => {
    const db = bb.storage.database();
    bb.storage.migrate(db, [
      "CREATE TABLE snapshots (id TEXT PRIMARY KEY, repository TEXT NOT NULL, html TEXT NOT NULL, created_at INTEGER NOT NULL)"
    ]);
    return db;
  };
  bb.http.route(
    "GET",
    "/snapshot",
    (context) => {
      const id = context.req.query("id");
      if (!id || !/^[a-f0-9-]{36}$/.test(id))
        return new Response("Snapshot not found.", { status: 404 });
      const snapshot = snapshots().prepare("SELECT repository, html FROM snapshots WHERE id = ?").get(id);
      if (!snapshot) return new Response("Snapshot not found.", { status: 404 });
      return new Response(snapshot.html, {
        headers: {
          "Content-Type": "text/html; charset=utf-8",
          "Content-Disposition": `attachment; filename="brocante-${snapshot.repository.replace("/", "-")}.html"`,
          "Cache-Control": "no-store",
          "X-Content-Type-Options": "nosniff",
          "Content-Security-Policy": "sandbox allow-scripts allow-popups"
        }
      });
    },
    { auth: "local" }
  );
  bb.cli.register(
    defineCli({
      name: "brocante",
      summary: "Save portable 3D pull-request markets",
      commands: {
        report: cliCommand({
          summary: "Save a repository\u2019s 3D market, or export Markdown / JSON",
          positionals: [{ name: "repository", description: "GitHub owner/repository" }],
          options: {
            format: {
              type: "enum",
              values: ["html", "markdown", "json"],
              default: "html",
              description: "3D snapshot or text export format"
            },
            search: {
              type: "string",
              description: "Search this repository\u2019s open pull requests (max 256 characters)"
            },
            "max-pages": {
              type: "string",
              default: "10",
              description: "Page limit, 60 PRs per page (1-100)"
            },
            demo: { type: "boolean", description: "Save a fictional market without credentials" }
          },
          async run(input) {
            const { githubToken } = await settings.get();
            if (!githubToken && !input.options.demo)
              throw new PluginCliError(
                "Configure a GitHub token in the Brocante plugin settings.",
                { code: "missing_token" }
              );
            if (!input.options.demo && Date.now() < retryAt)
              throw new PluginCliError(
                `GitHub is rate limited. Retry after ${Math.ceil((retryAt - Date.now()) / 1e3)} seconds.`,
                { code: "rate_limited" }
              );
            try {
              const maxPages = Number(input.options["max-pages"]);
              if (!/^\d+$/.test(input.options["max-pages"]) || maxPages < 1 || maxPages > 100)
                throw new Error("--max-pages must be an integer from 1 to 100.");
              if (input.options.demo && (input.positionals.repository || input.options.search))
                throw new Error("Use --demo without a repository or search.");
              const report = input.options.demo ? { ...reportFromSnapshot(demoMarket()), demo: true } : await generateReport({
                repository: input.positionals.repository ?? "",
                token: githubToken,
                search: input.options.search,
                // Bound text output; HTML is stored separately and never sent through CLI stdout.
                maxPages: input.options.format === "html" ? maxPages : 1
              });
              if (input.options.format === "html") {
                const id = randomUUID();
                const db = snapshots();
                db.prepare(
                  "INSERT INTO snapshots (id, repository, html, created_at) VALUES (?, ?, ?, ?)"
                ).run(id, report.repository, renderSnapshot(report), Date.now());
                db.prepare(
                  "DELETE FROM snapshots WHERE id NOT IN (SELECT id FROM snapshots ORDER BY created_at DESC, rowid DESC LIMIT 10)"
                ).run();
                const path = `/api/v1/plugins/${encodeURIComponent(bb.pluginId)}/http/snapshot?id=${id}`;
                const url = new URL(
                  path,
                  bb.server.experimental_appUrl ?? bb.server.loopbackBaseUrl
                ).href;
                return {
                  exitCode: 0,
                  stdout: `Portable 3D market: ${url}
Download the HTML and open it in your browser.
${report.complete ? "" : "Partial snapshot: increase --max-pages or narrow --search for more results.\n"}`
                };
              }
              report.pullRequests = report.pullRequests.map((pr) => ({
                ...pr,
                body: "",
                bodyTruncated: pr.bodyTruncated || pr.body.length > 0
              }));
              return {
                exitCode: 0,
                stdout: renderReport(report, input.options.format, {
                  partialHint: "Narrow --search, or use the standalone brocante CLI for more pages."
                })
              };
            } catch (error) {
              if (error instanceof GitHubError && error.status === 429)
                retryAt = Date.now() + (error.retryAfter ?? 60) * 1e3;
              const message = error instanceof GitHubError ? `${error.status === 401 ? "GitHub rejected the configured token." : error.message}${error.retryAfter ? ` Retry after ${error.retryAfter} seconds.` : ""}` : error instanceof TypeError ? "Unable to reach GitHub. Please retry." : error instanceof Error ? error.message : "Report generation failed.";
              throw new PluginCliError(message, {
                code: error instanceof GitHubError && error.status === 429 ? "rate_limited" : "report_failed"
              });
            }
          }
        })
      }
    })
  );
}
export {
  plugin as default
};
